//! canonical-agent-stages.rs — twin of skills/engine/canonical-agent-stages.mjs: DATA statics pressed by the crossing + the
//! hand-ported accessor. NAMES ARE CONTRACT: statics and fns carry exact JS names.
// QUALITY: 80/100 — pressed statics + trivial hand accessor; blob unreadable by design, surface fully tested
use serde_json::Value;
use std::sync::LazyLock;

pub static CANONICAL_AGENT_STAGES: LazyLock<Value> = LazyLock::new(|| {
    serde_json::from_str(r#"[{"agent_name":"pl","stage_name":"start","order_index":0,"pipeline_order":0,"fe_group":"plan","description_md":"Create pl_sessions row from raw_intent; lint defer phrases.","entry_signal":"card backlog AND user-prioritized AND no pl_session","exit_signal":"pl_session.status=clarifying","actions":[{"action_name":"pl.session.start","invocation_pattern":"always","rationale_md":"executor: pl-start"}]},{"agent_name":"pl","stage_name":"clarify","order_index":1,"pipeline_order":1,"fe_group":"plan","description_md":"Generate clarifying questions via AI; advance clarifying → researching. Skipped when confidence is already high.","entry_signal":"pl_session.status=clarifying","exit_signal":"pl_session.status=researching","actions":[{"action_name":"pl.session.advance.clarify","invocation_pattern":"conditional","rationale_md":"executor: pl-clarifying (skippable on high confidence)"}]},{"agent_name":"pl","stage_name":"research","order_index":2,"pipeline_order":2,"fe_group":"plan","description_md":"Pull RAG context over cards/memories/laws/knowledge + AI summary into pl_research_findings rows.","entry_signal":"pl_session.status=researching","exit_signal":"pl_session.status=deciding_split","actions":[{"action_name":"pl.session.advance.research","invocation_pattern":"always","rationale_md":"executor: pl-researching"}]},{"agent_name":"pl","stage_name":"decompose","order_index":3,"pipeline_order":3,"fe_group":"plan","description_md":"AI decides is_atomic; if false, spawns child pl_sessions for each split.","entry_signal":"pl_session.status=deciding_split","exit_signal":"pl_session.status=tuning","actions":[{"action_name":"pl.session.advance.decompose","invocation_pattern":"always","rationale_md":"executor: pl-deciding-split"}]},{"agent_name":"pl","stage_name":"finalize","order_index":4,"pipeline_order":4,"fe_group":"plan","description_md":"Assemble pl_proposed_cards row awaiting user approval.","entry_signal":"pl_session.status=tuning","exit_signal":"pl_session.status=awaiting_approval","actions":[{"action_name":"pl.session.finalize","invocation_pattern":"always","rationale_md":"executor: pl-tuning"}]},{"agent_name":"pl","stage_name":"approve","order_index":5,"pipeline_order":5,"fe_group":"plan","description_md":"Approve the proposed card(s) → cards table via with-audit. Auto-approved by the driver (approved_by=driver:auto) when ANTILOKI_AUTO_APPROVE is on (default); =off pauses for a human to dispatch (approved_by=that human).","entry_signal":"pl_session.status=awaiting_approval","exit_signal":"pl_session.status=done","actions":[{"action_name":"pl.session.approve","invocation_pattern":"always","rationale_md":"executor: pl-awaiting-approval"}]},{"agent_name":"tl","stage_name":"draft","order_index":0,"pipeline_order":6,"fe_group":"plan","description_md":"Auto-draft a contract from a ratified card using AST + RAG + templates.","entry_signal":"pl_session.status=done (or skip_pl card)","exit_signal":"contract status=proposed","actions":[{"action_name":"contract.draft.auto","invocation_pattern":"always","rationale_md":"executor: pl-done-no-contract / skip-pl-route"}]},{"agent_name":"tl","stage_name":"redraft","order_index":1,"pipeline_order":7,"fe_group":"plan","description_md":"Re-draft a rejected contract (rejection recovery / operator restart). Capped at 2 auto-redrafts before human escalation.","entry_signal":"contract status=rejected AND rejection_reason_md AND under cap","exit_signal":"new contract status=proposed","actions":[{"action_name":"tl.contract.redraft","invocation_pattern":"conditional","rationale_md":"executor: contract-rejected-redo (only on rejection, under cap)"}]},{"agent_name":"pl","stage_name":"ratify","order_index":6,"pipeline_order":8,"fe_group":"plan","description_md":"PL ratifies the proposed contract (gate before TL signs).","entry_signal":"contract status=proposed","exit_signal":"contract status=pl_ratified","actions":[{"action_name":"card.gate.pl.ratify","invocation_pattern":"always","rationale_md":"executor: contract-proposed"}]},{"agent_name":"tl","stage_name":"plan","order_index":2,"pipeline_order":9,"fe_group":"plan","description_md":"Plan the contract into per-file microtask DEFINITIONS (briefing + defs, patches empty — no code). Required for size M/L; re-fires when the plan review bounces the decomposition.","entry_signal":"contract status=pl_ratified AND size in (M,L) AND no plan defs","exit_signal":"microtasks_json holds defs (patches empty)","actions":[{"action_name":"tl.plan.contract","invocation_pattern":"conditional","rationale_md":"executor: contract-pl-ratified-needs-plan (M/L only) + contract-plan-coverage-failed-retry"}]},{"agent_name":"qa","stage_name":"plan_coverage","order_index":0,"pipeline_order":9.2,"fe_group":"plan","description_md":"DETERMINISTIC plan-coverage gate (no AI): for each STATIC acceptance (file-exists, grep-in-a-test-command) checks the plan covers it. Exhaustive, no false blockers — RED converges the re-plan loop in one round. Runs FIRST, before the AI review.","entry_signal":"plan defs present AND not all authored AND no fresh coverage verdict","exit_signal":"contract_qa_reviews row written (review_mode=plan-coverage)","actions":[{"action_name":"qa.contract.plan.coverage","invocation_pattern":"conditional","rationale_md":"executor: contract-planned-needs-plan-coverage"}]},{"agent_name":"qa","stage_name":"plan_review","order_index":1,"pipeline_order":9.3,"fe_group":"plan","description_md":"QA reviews the DECOMPOSITION (defs without patches, mode=plan) for OPEN-ENDED quality the deterministic gate cannot judge. Runs SECOND, after coverage is GREEN. Advisory at the microtask level (snippets proceed); can still escalate a CONTRACT-level impossibility.","entry_signal":"plan defs present AND not all authored AND coverage GREEN AND no fresh plan review","exit_signal":"contract_qa_reviews row written (review_mode=plan)","actions":[{"action_name":"qa.contract.review","invocation_pattern":"conditional","rationale_md":"executor: contract-planned-needs-plan-review (mode=plan via action-input-builder)"}]},{"agent_name":"tl","stage_name":"author-snippets","order_index":3,"pipeline_order":9.6,"fe_group":"plan","description_md":"Author the literal per-file patches for the reviewed plan (one small AI call per file with deterministic gates). Also the re-author target for QA-fail / red-build-gate retries (sliced when the failure maps to a minority of files).","entry_signal":"plan defs present AND fresh GREEN plan review","exit_signal":"every microtask carries patches","actions":[{"action_name":"tl.author.snippets","invocation_pattern":"conditional","rationale_md":"executor: contract-planned-needs-snippets + contract-impl-qa-failed-retry + contract-impl-build-gate-failed-retry + contract-tl-approved-qa-review-failed-retry"}]},{"agent_name":"tl","stage_name":"sign","order_index":4,"pipeline_order":10,"fe_group":"plan","description_md":"Review the ratified draft + write briefing/evaluation + sign (→ tl_approved) or reject.","entry_signal":"contract status=pl_ratified","exit_signal":"contract status=tl_approved|rejected","actions":[{"action_name":"contract.gate.tl.sign","invocation_pattern":"always","rationale_md":"executor: contract-pl-ratified"}]},{"agent_name":"pl","stage_name":"review","order_index":7,"pipeline_order":11,"fe_group":"plan","description_md":"PL reviews TL's signed contract (handshake before MAN). Returns signed|pushback; pushback loops back to redraft.","entry_signal":"contract status=tl_approved AND pl_review_count=0","exit_signal":"pl_review_count>=1","actions":[{"action_name":"pl.review.contract","invocation_pattern":"always","rationale_md":"executor: contract-tl-approved-needs-pl-review"}]},{"agent_name":"qa","stage_name":"contract_review","order_index":2,"pipeline_order":11.5,"fe_group":"plan","description_md":"QA #1 (shift-left): the thinking gate that reviews the contract + microtasks + literal patches BEFORE DEV. Fail bounces back to TL re-author; pass lets MAN/sandbox/DEV proceed.","entry_signal":"contract status=tl_approved AND pl_review_count>=1 AND no fresh QA contract review","exit_signal":"contract_qa_reviews row written","actions":[{"action_name":"qa.contract.review","invocation_pattern":"always","rationale_md":"executor: contract-tl-approved-needs-qa-review"}]},{"agent_name":"man","stage_name":"contract_audit","order_index":0,"pipeline_order":12,"fe_group":"plan","description_md":"MAN Phase 1: audit the just-signed contract against deterministic criteria (files_touched, acceptance, must_obey) before sandbox/DEV.","entry_signal":"contract status=tl_approved AND pl_review_count>=1 AND fresh green QA contract review AND !man_phase1_passed","exit_signal":"man_phase1_passed=1","actions":[{"action_name":"man.audit.contract.signed","invocation_pattern":"always","rationale_md":"executor: contract-tl-approved-needs-man-phase1"}]},{"agent_name":"tl","stage_name":"sandbox","order_index":5,"pipeline_order":13,"fe_group":"build","description_md":"Create the copy-on-write sandbox for the approved contract before DEV starts.","entry_signal":"contract status=tl_approved AND man_phase1_passed AND !sandbox_path","exit_signal":"sandbox_path set","actions":[{"action_name":"tl.sandbox.create","invocation_pattern":"always","rationale_md":"executor: contract-tl-approved-no-sandbox"}]},{"agent_name":"git-manager","stage_name":"implement","order_index":0,"pipeline_order":14,"fe_group":"build","description_md":"DEV applies TL's authored patches scoped to contract.files_touched; advances contract.status to impl.","entry_signal":"contract status=tl_approved AND man_phase1_passed AND sandbox_path (or human_approved)","exit_signal":"contract status=impl","actions":[{"action_name":"git-manager.implement.code","invocation_pattern":"always","rationale_md":"executor: contract-tl-approved / contract-human-approved"}]},{"agent_name":"git-manager","stage_name":"build_gate","order_index":1,"pipeline_order":14.5,"fe_group":"build","description_md":"Deterministic build/compile gate: run the contract build_cmd against the sandbox after DEV applies. Green → QA; red → route back to tl.refine.microtasks with the real compiler errors. No build cmd → auto-skip.","entry_signal":"contract status=impl AND build gate not fresh for the latest implement tick","exit_signal":"build_gate_runs row written (passed or skipped)","actions":[{"action_name":"git-manager.build.gate","invocation_pattern":"conditional","rationale_md":"executor: contract-impl-needs-build-gate"}]},{"agent_name":"qa","stage_name":"gate","order_index":0,"pipeline_order":15,"fe_group":"build","description_md":"Verify scope + run acceptance items; roll up a verdict. All pass → contract status=done; any fail → routes back to TL re-author.","entry_signal":"contract status=impl (no qa run yet) OR status=qa","exit_signal":"contract status=done OR unchanged","actions":[{"action_name":"qa.gate.contract.verify","invocation_pattern":"always","rationale_md":"executor: contract-impl-no-qa / contract-qa"}]},{"agent_name":"tl","stage_name":"amend","order_index":6,"pipeline_order":16,"fe_group":"build","description_md":"Apply a QA-emitted contract amendment (e.g. widen files_touched) before DEV retries. Capped at TL_MAX_AMENDMENTS.","entry_signal":"contract status=impl AND QA failed AND has_unconsumed_amendment AND under cap","exit_signal":"amendment applied","actions":[{"action_name":"tl.contract.amend","invocation_pattern":"conditional","rationale_md":"executor: contract-impl-qa-failed-amendment-to-tl (only on scope amendment)"}]},{"agent_name":"man","stage_name":"review","order_index":1,"pipeline_order":17,"fe_group":"verify","description_md":"Post-QA: MAN audits the completed journey for the done contract.","entry_signal":"contract status=done AND !postQa.man","exit_signal":"man_reviewed phase event","actions":[{"action_name":"man.card.review","invocation_pattern":"conditional","rationale_md":"executor: contract-done-needs-man-review (post-QA; only after done)"}]},{"agent_name":"keeper","stage_name":"consolidate","order_index":0,"pipeline_order":18,"fe_group":"verify","description_md":"Post-QA: Keeper distills lessons from the completed card into memory.","entry_signal":"contract status=done AND postQa.man AND !postQa.keeper","exit_signal":"keeper_consolidated phase event","actions":[{"action_name":"keeper.card.consolidate","invocation_pattern":"conditional","rationale_md":"executor: contract-done-needs-keeper-consolidate (post-QA)"}]},{"agent_name":"keeper","stage_name":"journey","order_index":1,"pipeline_order":19,"fe_group":"verify","description_md":"Post-QA: append the consolidated lesson to project_journey.","entry_signal":"contract status=done AND postQa.man AND postQa.keeper AND !postQa.journey","exit_signal":"journey_appended phase event","actions":[{"action_name":"keeper.journey.append","invocation_pattern":"conditional","rationale_md":"executor: contract-done-needs-journey-append (post-QA)"}]},{"agent_name":"board-keeper","stage_name":"blueprint","order_index":0,"pipeline_order":20,"fe_group":"verify","description_md":"Post-QA: freeze the review blueprint (diff + per-AC anchors + narrative) as the last reflection step.","entry_signal":"contract status=done AND postQa.man/keeper/journey AND !postQa.blueprint","exit_signal":"frozen card_review_blueprints row","actions":[{"action_name":"board-keeper.card.review.blueprint.generate","invocation_pattern":"conditional","rationale_md":"executor: contract-done-needs-review-blueprint (post-QA)"}]},{"agent_name":"board-keeper","stage_name":"close","order_index":1,"pipeline_order":21,"fe_group":"verify","description_md":"Seal: flip cards.status to done once the full post-QA chain is complete.","entry_signal":"contract status=done AND card.status!=done AND postQa.man/keeper/journey/blueprint","exit_signal":"cards.status=done","actions":[{"action_name":"board-keeper.card.status.change","invocation_pattern":"conditional","rationale_md":"executor: contract-done-card-needs-close (post-QA seal)"}]}]"#).expect("CANONICAL_AGENT_STAGES: embedded JSON is valid by construction")
});

/// JS: `canonicalAgentStages(_input, _context)` — returns the canonical data, verbatim.
pub fn canonicalAgentStages(_input: &Value, _context: &Value) -> Value {
    CANONICAL_AGENT_STAGES.clone()
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::Value;

    #[test]
    fn canonical_agent_stages_parses_with_the_pressed_shape() {
        let v: &Value = &CANONICAL_AGENT_STAGES;
        let a = v.as_array().expect("array");
        assert_eq!(a.len(), 27, "pressed length");
    }

    #[test]
    fn canonicalagentstages_returns_the_static_verbatim() {
        assert_eq!(canonicalAgentStages(&Value::Null, &Value::Null), *CANONICAL_AGENT_STAGES);
    }

}
